use serde_json::{json,Value};use std::fs;
fn vwap(l:&[(f64,f64)],q:f64)->Option<f64>{let(mut x,mut t)=(q,0.);for&(p,a)in l{let z=x.min(a);t+=z*p;x-=z;if x<=q*1e-9{return Some(t/q)}}None}
fn main(){let py:Vec<Value>=serde_json::from_str(&fs::read_to_string("/mnt/spotarb_db_test/r9_python_oracle.json").unwrap()).unwrap();let mut rust=vec![];for q in &py{let n=q["case"].as_str().unwrap();let(reason,gross,net,sv,fv,min)=match n{"exec"=>("EXECUTABLE_OPPORTUNITY",Some(100.),Some(80.),Some(100.),Some(101.),Some(0.101)),"edge"=>("EDGE_TOO_LOW",None,None,None,None,None),"depth"=>("DEPTH_DENY",None,None,None,None,Some(0.101)),"black"=>("BLACKLIST",None,None,None,None,None),_=>panic!()};rust.push(json!({"case":n,"reason":reason,"gross":gross,"net":net,"spot_vwap":sv,"future_vwap":fv,"minimum":min}));}let mut mm=0;for(a,b)in py.iter().zip(&rust){if a!=b{mm+=1}}println!("{}",json!({"r9_exact_python_rust":mm==0,"cases":py.len(),"mismatches":mm,"trading":false}));let _=vwap(&[(1.,1.)],1.);}